  if (!cands.length) return false;
  cands.sort((a, b) => (b.cu.vip - a.cu.vip) || (a.r - b.r)); // VIPs always first
  const { cu, i } = cands[0];
  const idx = cu.order.findIndex(o => !o.done && o.id === id); cu.order[idx].done = true;
  const g = bubbleGeom(i, cu);
  fx({ type: 'item', id, x: sx, y: sy, tx: g.cx - 10, ty: g.top + 10 + idx * g.ih + g.ih / 2, life: .35 });
  cu.p = Math.min(cu.maxP, cu.p + cu.maxP * .08); cu.joy = .8;
