  fx({ type: 'burst', x, y: fy + 20, life: .6, col: '#FFD45E' });
  for (let k = 0; k < 2; k++) fx({ type: 'heart', x: x + rand(-40, 40), y: fy + 30, life: 1.1 + k * .2 });
