    const di = sl.findIndex(s => s.s === 'done'), e = sl.find(s => s.s === 'empty');
    if (di >= 0 && demand(item) > 0) { const p = slotPos(id, di); if (serve(item, p.x, p.y)) { Object.assign(sl[di], newSlot()); syncSlots(id); } }
    else if (e) { Object.assign(e, { s: 'cook', t: 0, bt: 0 }); sfx('pop'); ev(id); }
    else if (di >= 0) { shake(id); toast('No cat ordered this yet'); }
