function drawFireworks(c) {
  FX.forEach(f => {
    const k = f.t / f.life;
    if (f.type === 'rocket') { const y = f.y0 + (f.ty - f.y0) * ease(k); c.globalAlpha = 1; circ(c, f.x, y, 4); c.fillStyle = '#FFF6C8'; c.fill(); for (let i = 1; i < 6; i++) { circ(c, f.x + Math.sin(i + f.t * 20) * 1.5, y + i * 9, 3 - i * .4); c.fillStyle = `rgba(255,214,120,${.7 - i * .12})`; c.fill(); } }
    if (f.type === 'spark') { const x = f.x + f.vx * f.t, y = f.y + f.vy * f.t + 110 * f.t * f.t; c.globalAlpha = Math.max(0, 1 - k); sparkle(c, x, y, 5 * (1 - k * .5), f.col); c.globalAlpha = 1; }
    if (f.type === 'conf') { const x = f.x + f.vx * f.t + Math.sin(f.t * 4 + f.rot) * 16, y = f.y + f.vy * f.t; c.save(); c.globalAlpha = Math.min(1, (1 - k) * 3); c.translate(x, y); c.rotate(f.rot + f.vr * f.t); c.fillStyle = f.col; c.fillRect(-5, -3, 10, 6); c.restore(); }
  });
}
